CREATE OR REPLACE FUNCTION public.accept_helios_handoff_v1(p_prep_id uuid, p_verifications jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role; v_status public.prep_status; v_item record; v_verify jsonb; v_actual int; v_required int;
  v_it_photos int; v_service_photos int; v_parts_total int; v_parts_confirmed boolean; v_name text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Service or Owner access required'; end if;
  select status,(solar_panel_qty+battery_replacement_qty+camera_replacement_qty+sim_replacement_qty+micro_sd_qty),service_parts_confirmed
  into v_status,v_parts_total,v_parts_confirmed from public.prep_tickets where id=p_prep_id;
  if not found or v_status<>'released' then raise exception 'Service handoff not found or no longer waiting for Service'; end if;
  if not exists(select 1 from public.prep_items where prep_ticket_id=p_prep_id and equipment_type='Helios' and purpose in ('DELIVERY','SWAP')) then raise exception 'This handoff does not require the Helios field workflow'; end if;
  if coalesce(v_parts_total,0)>0 and not coalesce(v_parts_confirmed,false) then raise exception 'Verify the listed parts from IT before accepting this equipment'; end if;
  if jsonb_typeof(p_verifications)<>'array' then raise exception 'Equipment checkout verifications are required'; end if;
  for v_item in select * from public.prep_items where prep_ticket_id=p_prep_id order by item_order loop
    select value into v_verify from jsonb_array_elements(p_verifications) where value->>'item_id'=v_item.id::text limit 1;
    if v_verify is null then raise exception 'Missing equipment checkout verification for item %',v_item.item_order; end if;
    if trim(v_verify->>'unit_tag') is distinct from v_item.unit_tag then raise exception 'Unit tag does not match IT-prepared item %',v_item.item_order; end if;
    v_required:=coalesce(v_item.required_battery_count,0);
    if v_required>0 then
      v_actual:=coalesce((v_verify->>'battery_count')::int,-1);
      if v_actual<>v_item.battery_count or v_actual<v_required then raise exception 'Battery count does not match the IT-prepared item %',v_item.item_order; end if;
      if coalesce((v_verify->>'battery_verified')::boolean,false) is not true then raise exception 'Battery verification is required for item %',v_item.item_order; end if;
    else v_actual:=null; end if;
    if coalesce((v_verify->>'unit_confirmed')::boolean,false) is not true then raise exception 'Exact item confirmation is required for item %',v_item.item_order; end if;
    update public.prep_items set service_battery_count=v_actual,service_unit_confirmed=true,service_verified_by=auth.uid(),service_verified_at=now() where id=v_item.id;
  end loop;
  select count(*) into v_it_photos from public.handoff_evidence where prep_ticket_id=p_prep_id and stage='it' and kind='photo';
  if v_it_photos<1 then raise exception 'IT handoff photo proof is required before Service can accept the equipment'; end if;
  if not exists(select 1 from public.handoff_evidence where prep_ticket_id=p_prep_id and stage='service' and kind='signature') then raise exception 'Service receipt signature is required'; end if;
  if not exists(select 1 from public.service_solar_checks where prep_ticket_id=p_prep_id and completed_at is not null) then raise exception 'Complete the Helios yard solar test before accepting the handoff'; end if;
  if not exists(select 1 from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_yard' and kind='photo') then raise exception 'Helios yard-test photo proof is required'; end if;
  if not exists(select 1 from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_yard' and kind='signature') then raise exception 'Helios yard-test signature is required'; end if;
  v_name:=public.actor_display_name();
  update public.service_solar_checks set handoff_accepted_at=now(),handoff_accepted_by=auth.uid(),handoff_accepted_by_name=v_name,updated_at=now() where prep_ticket_id=p_prep_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_my_department_assignment(p_assignment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_assignment public.job_assignments%rowtype;
  v_name text;
  v_is_owner boolean;
  v_departure jsonb;
begin
  select * into v_profile from public.profiles where user_id=auth.uid() and active=true;
  if not found then raise exception 'Active account required.'; end if;
  v_is_owner := v_profile.role='owner';

  select * into v_assignment from public.job_assignments where id=p_assignment_id for update;
  if not found then raise exception 'Assignment not found.'; end if;
  if v_assignment.assignment_scope<>'department' or v_assignment.assignee_user_id is not null or v_assignment.status<>'assigned' then
    raise exception 'This department task has already been claimed or is no longer available.';
  end if;
  if not v_is_owner and v_assignment.assigned_role<>v_profile.role::text then
    raise exception 'This task belongs to a different technician department.';
  end if;

  if not v_is_owner
     and v_assignment.assigned_role='it'
     and lower(coalesce(v_assignment.work_type,''))='pickup'
     and not exists(
       select 1 from public.unit_returns r
       where trim(r.ticket_no)=trim(v_assignment.ticket_no)
         and r.status='waiting_it'
     ) then
    raise exception 'WAITING FOR SERVICE RETURN. This IT task is not available to claim yet.';
  end if;

  if not v_is_owner
     and v_assignment.assigned_role='service'
     and coalesce(v_assignment.requires_it_handoff,false)
     and not exists(
       select 1 from public.prep_tickets p
       where trim(p.ticket_no)=trim(v_assignment.ticket_no)
         and p.status in ('released','closed')
     ) then
    raise exception 'WAITING FOR IT HANDOFF. This Service task is not available to claim yet.';
  end if;

  if not v_is_owner and v_assignment.assigned_role='service' then
    v_departure:=public.service_departure_readiness_v1(auth.uid());
    if coalesce((v_departure->>'departure_ready')::boolean,false) is not true then
      raise exception 'NOT READY TO LEAVE SHOP. Complete the daily Truck / Trailer Inspection and required permanent truck inventory check/restock before claiming a new Service job.';
    end if;
  end if;

  v_name := coalesce(v_profile.full_name,v_profile.username,case when v_is_owner then 'Owner/Admin' else 'Technician' end);

  update public.job_assignments
  set assignee_user_id=auth.uid(),
      assignee_name=v_name,
      status='started',
      started_at=coalesce(started_at,now()),
      claimed_at=now(),
      updated_at=now()
  where id=p_assignment_id;

  update public.app_notifications
  set read_at=coalesce(read_at,now())
  where assignment_id=p_assignment_id and recipient_user_id<>auth.uid();

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'DEPARTMENT TASK CLAIMED',auth.uid(),v_name,v_assignment.ticket_no,
    (case when v_assignment.assigned_role='it' then 'IT ' else 'Service ' end)||
    case when v_is_owner then 'Owner preview ' else 'Tech ' end||
    v_name||' claimed the department task and started the process.'
  );

  return p_assignment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_service_parts(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_name text;
begin
  perform public.require_role(array['service'::public.app_role,'owner'::public.app_role]);

  if not exists (
    select 1 from public.prep_tickets
    where id=p_prep_id and status='released'
  ) then
    raise exception 'Service handoff not found or no longer waiting for Service.';
  end if;

  v_name := public.actor_display_name();
  update public.prep_tickets
  set service_parts_confirmed=true,
      service_parts_confirmed_by=auth.uid(),
      service_parts_confirmed_by_name=v_name,
      service_parts_confirmed_at=now()
  where id=p_prep_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.it_confirm_swap_site_registration_v1(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_item public.prep_items%rowtype;
  v_prep public.prep_tickets%rowtype;
  v_name text;
  v_key text;
  v_asset public.asset_inventory%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('it'::public.app_role,'owner'::public.app_role) then
    raise exception 'IT or Owner access required';
  end if;

  select * into v_item
  from public.prep_items
  where id=p_item_id
  for update;

  if not found
     or v_item.purpose<>'SWAP'::public.prep_purpose
     or v_item.swap_outcome<>'installed' then
    raise exception 'Installed SWAP unit not found';
  end if;

  if v_item.swap_site_registration_status='completed' then
    return jsonb_build_object('item_id',v_item.id,'status','completed','already_recorded',true);
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=v_item.prep_ticket_id;

  if not found then raise exception 'SWAP prep record not found'; end if;

  v_name:=public.actor_display_name();
  v_key:=public.normalize_unit_key(v_item.unit_tag);

  update public.prep_items
  set swap_site_registration_status='completed',
      swap_site_registered_by=auth.uid(),
      swap_site_registered_by_name=v_name,
      swap_site_registered_at=now(),
      swap_installed_site=coalesce(
        nullif(trim(swap_installed_site),''),
        nullif(trim(coalesce(v_prep.site,'')),'')
      )
  where id=v_item.id;

  update public.unit_registry
  set lifecycle_status='deployed',
      ticket_no=v_prep.ticket_no,
      prep_ticket_id=v_prep.id,
      prep_item_id=v_item.id,
      current_site=coalesce(
        nullif(trim(v_item.swap_installed_site),''),
        nullif(trim(coalesce(v_prep.site,'')),'')
      ),
      site_registered_at=now(),
      site_registered_by=auth.uid(),
      site_registered_by_name=v_name,
      last_event='IT registered SWAP unit to '||
        coalesce(
          nullif(trim(v_item.swap_installed_site),''),
          nullif(trim(coalesce(v_prep.site,'')),''),
          'customer site'
        )||
        ' on MHelpDesk #'||v_prep.ticket_no,
      updated_at=now()
  where unit_key=v_key;

  select * into v_asset
  from public.asset_inventory
  where unit_key=v_key
  for update;

  if found then
    insert into public.asset_inventory_history(
      unit_key,unit_tag,action,from_status,to_status,
      from_user_id,from_user_name,to_user_id,to_user_name,
      actor_id,actor_name,notes
    )
    values(
      v_asset.unit_key,v_asset.unit_tag,'swap_site_registered',
      v_asset.availability_status,'assigned',
      v_asset.assigned_to,v_asset.assigned_to_name,
      v_asset.assigned_to,v_asset.assigned_to_name,
      auth.uid(),v_name,
      'IT registered SWAP unit to '||
      coalesce(
        nullif(trim(v_item.swap_installed_site),''),
        nullif(trim(coalesce(v_prep.site,'')),''),
        'customer site'
      )||
      ' for MHelpDesk #'||v_prep.ticket_no
    );

    update public.asset_inventory
    set availability_status='assigned',
        last_event='IT site registration complete for '||
          coalesce(
            nullif(trim(v_item.swap_installed_site),''),
            nullif(trim(coalesce(v_prep.site,'')),''),
            'customer site'
          )||
          ' · MHelpDesk #'||v_prep.ticket_no,
        updated_at=now()
    where unit_key=v_key;
  end if;

  update public.app_notifications
  set read_at=coalesce(read_at,now())
  where kind='swap_site_registration'
    and trim(coalesce(ticket_no,''))=trim(v_prep.ticket_no)
    and public.normalize_unit_key(unit_tag)=v_key;

  insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
  values(
    'SWAP SITE REGISTRATION COMPLETE',
    auth.uid(),v_name,v_prep.ticket_no,
    'IT registered replacement '||v_item.equipment_type||' '||v_item.unit_tag||
    ' to '||coalesce(
      nullif(trim(v_item.swap_installed_site),''),
      nullif(trim(coalesce(v_prep.site,'')),''),
      'the customer site'
    )||'.'
  );

  return jsonb_build_object(
    'item_id',v_item.id,
    'status','completed',
    'unit_tag',v_item.unit_tag,
    'site',coalesce(v_item.swap_installed_site,v_prep.site)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.link_my_assignment_to_prep(p_assignment_id uuid, p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_assignment public.job_assignments%rowtype;
  v_prep public.prep_tickets%rowtype;
begin
  select * into v_assignment
  from public.job_assignments
  where id=p_assignment_id
    and assignee_user_id=auth.uid()
    and status in ('assigned','started')
  for update;
  if not found then raise exception 'Assignment not found or no longer active.'; end if;

  select * into v_prep
  from public.prep_tickets
  where id=p_prep_id;
  if not found then raise exception 'Equipment prep not found.'; end if;

  if trim(v_assignment.ticket_no)<>trim(v_prep.ticket_no) then
    raise exception 'The Tech Check prep does not match the assigned MHelpDesk reference.';
  end if;

  update public.job_assignments
  set prep_ticket_id=p_prep_id,
      status='started',
      started_at=coalesce(started_at,now()),
      updated_at=now()
  where id=p_assignment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.owner_verify_helios_install_v1(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_status public.prep_status; v_ticket text; v_test boolean; v_name text; v_helios int:=0; v_swaps int:=0; v_returns int:=0;
begin
  perform public.require_role(array['owner'::public.app_role]);
  select status,ticket_no,is_test into v_status,v_ticket,v_test from public.prep_tickets where id=p_prep_id for update;
  if not found or v_status<>'released' then raise exception 'Helios job is not waiting for Owner verification'; end if;
  select count(*) filter(where equipment_type='Helios' and purpose in ('DELIVERY','SWAP')),count(*) filter(where equipment_type='Helios' and purpose='SWAP')
  into v_helios,v_swaps from public.prep_items where prep_ticket_id=p_prep_id;
  if v_helios<1 then raise exception 'No field-installed Helios is on this ticket'; end if;
  if not exists(select 1 from public.service_solar_checks where prep_ticket_id=p_prep_id and helios_field_completed_at is not null) then raise exception 'Service has not submitted the Helios field installation'; end if;
  if (select count(*) from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_install' and kind='photo')<v_helios then raise exception 'Final Helios installation photo proof is incomplete'; end if;
  if not exists(select 1 from public.service_solar_evidence where prep_ticket_id=p_prep_id and category='helios_install' and kind='signature') then raise exception 'Final Helios installation signature is missing'; end if;
  if v_swaps>0 then
    select count(*) into v_returns from public.unit_returns
    where trim(ticket_no)=trim(v_ticket) and equipment_type='Helios' and coalesce(array_length(return_photo_paths,1),0)>0
      and nullif(trim(coalesce(return_notes,'')),'') is not null and coalesce(tag_scan_status,'')<>'mismatch';
    if v_returns<v_swaps then raise exception 'OLD UNIT RETURNING documentation is incomplete for this Helios SWAP'; end if;
  end if;
  if exists(select 1 from public.prep_items where prep_ticket_id=p_prep_id and purpose='BACKUP' and spare_outcome is null) then raise exception 'Resolve every checked-out truck spare as USED FOR SWAP or RETURN UNUSED TO SHOP before final Owner verification'; end if;
  v_name:=public.actor_display_name();
  update public.service_solar_checks set helios_owner_verified_at=now(),helios_owner_verified_by=auth.uid(),helios_owner_verified_by_name=v_name,updated_at=now() where prep_ticket_id=p_prep_id;
  update public.prep_tickets set status='closed',closed_by=auth.uid(),closed_by_name=v_name,closed_at=now() where id=p_prep_id;
  update public.job_assignments set prep_ticket_id=p_prep_id,status='completed',completed_at=now(),updated_at=now()
  where assigned_role='service' and ticket_no=v_ticket and status in ('assigned','started');
  insert into public.reports(kind,actor_id,actor_name,ticket_no,text,is_test)
  values(case when coalesce(v_test,false) then 'TEST HELIOS OWNER FINAL VERIFIED' else 'HELIOS OWNER FINAL VERIFIED' end,
    auth.uid(),v_name,v_ticket,
    'Owner '||v_name||' reviewed the Helios field-install checklist, final photos, timestamped Service signature, and any OLD UNIT RETURNING swap documentation. The Helios deployment is final verified.',
    coalesce(v_test,false));
end;
$function$

CREATE OR REPLACE FUNCTION public.record_handoff_evidence(p_prep_id uuid, p_stage text, p_kind text, p_storage_path text, p_original_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status public.prep_status;
  v_role public.app_role;
  v_id uuid;
  v_name text;
  v_original text;
  v_existing public.handoff_evidence%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role is null or v_role not in ('owner'::public.app_role,'it'::public.app_role,'service'::public.app_role) then
    raise exception 'Active technician access is required';
  end if;
  if p_stage not in ('it','service') then raise exception 'Invalid handoff stage'; end if;
  if p_kind not in ('photo','signature') then raise exception 'Invalid evidence type'; end if;
  if nullif(trim(p_storage_path),'') is null then raise exception 'Evidence file path is required'; end if;
  if split_part(p_storage_path,'/',1)<>auth.uid()::text then
    raise exception 'Evidence path does not belong to this technician';
  end if;

  select status into v_status
  from public.prep_tickets
  where id=p_prep_id
  for update;
  if not found then raise exception 'Equipment prep not found'; end if;

  if p_stage='it' then
    if v_role not in ('it'::public.app_role,'owner'::public.app_role) then
      raise exception 'Only IT or Owner can add IT handoff evidence';
    end if;
    if v_status<>'draft'::public.prep_status then
      raise exception 'IT handoff evidence can only be added before equipment is sent to Service';
    end if;
  else
    if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
      raise exception 'Only Service or Owner can add Service receipt evidence';
    end if;
    if v_status<>'released'::public.prep_status then
      raise exception 'Service receipt evidence can only be added while equipment is waiting for Service';
    end if;
  end if;

  select * into v_existing
  from public.handoff_evidence
  where storage_path=trim(p_storage_path)
  limit 1;

  if found then
    if v_existing.prep_ticket_id<>p_prep_id
       or v_existing.stage<>p_stage
       or v_existing.kind<>p_kind
       or v_existing.prep_item_id is not null
       or v_existing.created_by<>auth.uid() then
      raise exception 'This evidence file path is already attached to a different Tech Check record';
    end if;
    return v_existing.id;
  end if;

  v_name:=public.actor_display_name();
  v_original:=nullif(trim(p_original_name),'');

  if p_kind='signature' then
    if v_original is null then
      delete from public.handoff_evidence
      where prep_ticket_id=p_prep_id
        and stage=p_stage
        and kind='signature';
    else
      delete from public.handoff_evidence
      where prep_ticket_id=p_prep_id
        and stage=p_stage
        and kind='signature'
        and original_name=v_original;
    end if;
  end if;

  insert into public.handoff_evidence(
    prep_ticket_id,stage,kind,storage_path,original_name,created_by,created_by_name
  )
  values(
    p_prep_id,p_stage,p_kind,trim(p_storage_path),v_original,auth.uid(),v_name
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_unit_handoff_evidence(p_prep_id uuid, p_item_id uuid, p_stage text, p_kind text, p_storage_path text, p_original_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_status public.prep_status; v_role public.app_role; v_id uuid; v_name text;
begin
  v_role:=public.current_app_role();
  if v_role is null or v_role not in ('owner'::public.app_role,'it'::public.app_role,'service'::public.app_role) then raise exception 'Active technician access is required'; end if;
  if p_stage not in ('it','service') then raise exception 'Invalid handoff stage'; end if;
  if p_kind not in ('photo','signature') then raise exception 'Invalid evidence type'; end if;
  if nullif(trim(p_storage_path),'') is null then raise exception 'Evidence file path is required'; end if;
  if split_part(p_storage_path,'/',1)<>auth.uid()::text then raise exception 'Evidence path does not belong to this technician'; end if;
  select t.status into v_status from public.prep_items i join public.prep_tickets t on t.id=i.prep_ticket_id where i.id=p_item_id and i.prep_ticket_id=p_prep_id for update of i,t;
  if not found then raise exception 'Equipment unit not found'; end if;
  if p_stage='it' then
    if v_role not in ('it'::public.app_role,'owner'::public.app_role) then raise exception 'Only IT or Owner can add IT evidence'; end if;
    if v_status<>'draft'::public.prep_status then raise exception 'IT evidence can only be added before equipment is sent to Service'; end if;
  else
    if v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Only Service or Owner can add Service evidence'; end if;
    if v_status<>'released'::public.prep_status then raise exception 'Service evidence can only be added while equipment is waiting for Service'; end if;
  end if;
  v_name:=public.actor_display_name();
  delete from public.handoff_evidence where prep_ticket_id=p_prep_id and prep_item_id=p_item_id and stage=p_stage and kind=p_kind;
  insert into public.handoff_evidence(prep_ticket_id,prep_item_id,stage,kind,storage_path,original_name,created_by,created_by_name)
  values(p_prep_id,p_item_id,p_stage,p_kind,trim(p_storage_path),nullif(trim(p_original_name),''),auth.uid(),v_name)
  returning id into v_id;
  if p_stage='it' and p_kind='photo' then
    update public.prep_items set photo_tag_match_ok=false where id=p_item_id;
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_helios_field_install_v1(p_prep_id uuid, p_box_mounted_ok boolean, p_pv_connected_ok boolean, p_ptz_secured_ok boolean, p_switch_pv_ok boolean, p_unit_battery_on_ok boolean, p_it_online_verified_ok boolean, p_cameras_aimed_ok boolean, p_recording_ok boolean, p_tower_20ft_ok boolean, p_mast_lock_bolt_ok boolean, p_panel_45deg_ok boolean, p_panel_bolt_ok boolean, p_4_sandbags_ok boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_status public.prep_status;
  v_ticket text;
  v_is_test boolean;
  v_helios int:=0;
  v_swaps int:=0;
  v_returns int:=0;
  v_name text;
  v_complete boolean;
  v_check public.service_solar_checks%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select status,ticket_no,coalesce(is_test,false)
  into v_status,v_ticket,v_is_test
  from public.prep_tickets
  where id=p_prep_id
  for update;

  if not found or v_status<>'released' then
    raise exception 'Helios handoff is not open for field installation';
  end if;

  if v_role='service'::public.app_role and not exists(
    select 1
    from public.job_assignments a
    where a.assigned_role='service'
      and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started')
      and (
        a.prep_ticket_id=p_prep_id
        or (
          a.prep_ticket_id is null
          and btrim(a.ticket_no)=btrim(v_ticket)
        )
      )
      and (
        (v_is_test and a.created_from='owner_test_center')
        or
        (not v_is_test and coalesce(a.created_from,'')<>'owner_test_center')
      )
  ) then
    raise exception 'This Service handoff is not actively assigned to you';
  end if;

  select *
  into v_check
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id
  for update;

  if not found then
    raise exception 'Complete the Helios Service workflow before final submission';
  end if;

  if v_check.helios_field_completed_at is not null then
    return;
  end if;

  if exists(
    select 1 from public.prep_items
    where prep_ticket_id=p_prep_id
      and equipment_type='Helios'
      and purpose='SWAP'
      and swap_outcome is null
  ) then
    raise exception 'Answer whether each Helios SWAP replacement was actually installed before submitting the field installation.';
  end if;

  select
    count(*) filter(
      where equipment_type='Helios'
        and (
          purpose='DELIVERY'
          or (purpose='SWAP' and swap_outcome='installed')
        )
    ),
    count(*) filter(
      where equipment_type='Helios'
        and purpose='SWAP'
        and swap_outcome='installed'
    )
  into v_helios,v_swaps
  from public.prep_items
  where prep_ticket_id=p_prep_id;

  if v_helios<1 then
    raise exception 'No installed Helios remains on this ticket. Unused SWAP replacement units should return through IT Intake.';
  end if;

  if v_check.handoff_accepted_at is null then
    raise exception 'Accept the IT handoff after completing the yard test first';
  end if;

  if v_swaps>0 then
    select count(*) into v_returns
    from public.unit_returns r
    where btrim(r.ticket_no)=btrim(v_ticket)
      and r.equipment_type='Helios'
      and coalesce(array_length(r.return_photo_paths,1),0)>0
      and nullif(btrim(coalesce(r.return_notes,'')),'') is not null
      and coalesce(r.tag_scan_status,'')<>'mismatch'
      and not exists(
        select 1
        from public.prep_items replacement
        where replacement.prep_ticket_id=p_prep_id
          and replacement.purpose='SWAP'
          and public.normalize_unit_key(replacement.unit_tag)=public.normalize_unit_key(r.unit_tag)
      );

    if v_returns<v_swaps then
      raise exception 'Each installed Helios SWAP requires the OLD UNIT RETURNING tag photo, reason/issues/repair notes, and Service Return before final install submission';
    end if;
  end if;

  if (
    select count(*)
    from public.service_solar_evidence
    where prep_ticket_id=p_prep_id
      and category='helios_install'
      and kind='photo'
  )<v_helios then
    raise exception 'Upload at least one final installation photo for each installed Helios';
  end if;

  if not exists(
    select 1
    from public.service_solar_evidence
    where prep_ticket_id=p_prep_id
      and category='helios_install'
      and kind='signature'
  ) then
    raise exception 'A dated Service installation signature is required';
  end if;

  v_complete:=coalesce(p_box_mounted_ok,false)
    and coalesce(p_pv_connected_ok,false)
    and coalesce(p_ptz_secured_ok,false)
    and coalesce(p_switch_pv_ok,false)
    and coalesce(p_unit_battery_on_ok,false)
    and coalesce(p_it_online_verified_ok,false)
    and coalesce(p_cameras_aimed_ok,false)
    and coalesce(p_recording_ok,false)
    and coalesce(p_tower_20ft_ok,false)
    and coalesce(p_mast_lock_bolt_ok,false)
    and coalesce(p_panel_45deg_ok,false)
    and coalesce(p_panel_bolt_ok,false)
    and coalesce(p_4_sandbags_ok,false);

  if not v_complete then
    raise exception 'Complete every Helios field installation check before submitting to the Owner';
  end if;

  if not (
    coalesce(v_check.helios_field_box_mounted_ok,false)
    and coalesce(v_check.helios_field_pv_connected_ok,false)
    and coalesce(v_check.helios_field_ptz_secured_ok,false)
    and coalesce(v_check.helios_field_switch_pv_ok,false)
    and coalesce(v_check.helios_field_unit_battery_on_ok,false)
    and coalesce(v_check.helios_field_it_online_verified_ok,false)
    and coalesce(v_check.helios_field_cameras_aimed_ok,false)
    and coalesce(v_check.helios_field_panel_45deg_ok,false)
    and coalesce(v_check.helios_field_panel_bolt_ok,false)
    and coalesce(v_check.helios_field_tower_20ft_ok,false)
    and coalesce(v_check.helios_field_mast_lock_bolt_ok,false)
    and coalesce(v_check.helios_field_recording_ok,false)
    and coalesce(v_check.helios_field_4_sandbags_ok,false)
  ) then
    raise exception 'Saved Helios field-install steps are incomplete. Reload Tech Check and finish the required steps in order.';
  end if;

  v_name:=public.actor_display_name();

  update public.service_solar_checks
  set helios_field_completed_at=now(),
      helios_field_completed_by=auth.uid(),
      helios_field_completed_by_name=v_name,
      updated_at=now()
  where prep_ticket_id=p_prep_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_my_ranger_field_check_v1(p_item_id uuid, p_victron_updated_ok boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_prep_id uuid;
  v_ticket text;
  v_status public.prep_status;
  v_type text;
  v_purpose public.prep_purpose;
  v_swap_outcome text;
  v_already boolean;
  v_name text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Operations Manager access required';
  end if;

  select t.id,t.ticket_no,t.status,i.equipment_type,i.purpose,i.swap_outcome,
         coalesce(i.ranger_field_victron_updated_ok,false)
  into v_prep_id,v_ticket,v_status,v_type,v_purpose,v_swap_outcome,v_already
  from public.prep_items i
  join public.prep_tickets t on t.id=i.prep_ticket_id
  where i.id=p_item_id
  for update of i,t;

  if not found then raise exception 'Ranger prep item not found'; end if;
  if v_status<>'released'::public.prep_status then
    raise exception 'Ranger field verification is available only after the IT → Service handoff';
  end if;
  if v_type<>'Ranger'
     or not (
       v_purpose='DELIVERY'::public.prep_purpose
       or (v_purpose='SWAP'::public.prep_purpose and v_swap_outcome='installed')
     ) then
    raise exception 'Ranger field verification applies only to Ranger DELIVERY or an installed Ranger SWAP';
  end if;

  if v_role='service'::public.app_role and not exists(
    select 1
    from public.job_assignments a
    where a.assigned_role='service'
      and (a.prep_ticket_id=v_prep_id or btrim(a.ticket_no)=btrim(v_ticket))
      and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started','completed')
  ) then
    raise exception 'This Ranger field job is not assigned to you';
  end if;

  if not coalesce(p_victron_updated_ok,false) then
    raise exception 'Verify the Ranger is up to date in the Victron Bluetooth app before completing the field job';
  end if;

  if v_already then
    return;
  end if;

  v_name:=public.actor_display_name();

  update public.prep_items set
    ranger_field_victron_updated_ok=true,
    ranger_field_victron_updated_by=auth.uid(),
    ranger_field_victron_updated_by_name=v_name,
    ranger_field_victron_updated_at=now()
  where id=p_item_id
    and coalesce(ranger_field_victron_updated_ok,false)=false;

  if found then
    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values(
      'RANGER FIELD VICTRON VERIFIED',
      auth.uid(),
      v_name,
      v_ticket,
      'Service Tech '||v_name||' verified Ranger '||
        coalesce((select unit_tag from public.prep_items where id=p_item_id),'unit')||
        ' is up to date in the Victron Bluetooth app in the field.'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_service_helios_field_check_v1(p_prep_id uuid, p_field text, p_value boolean)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_ticket text;
  v_order text[]:=array[
    'helios_field_box_mounted_ok',
    'helios_field_pv_connected_ok',
    'helios_field_ptz_secured_ok',
    'helios_field_switch_pv_ok',
    'helios_field_unit_battery_on_ok',
    'helios_field_it_online_verified_ok',
    'helios_field_cameras_aimed_ok',
    'helios_field_panel_45deg_ok',
    'helios_field_panel_bolt_ok',
    'helios_field_tower_20ft_ok',
    'helios_field_mast_lock_bolt_ok',
    'helios_field_recording_ok',
    'helios_field_4_sandbags_ok'
  ];
  v_pos integer;
  v_i integer;
  v_prior boolean;
  v_row public.service_solar_checks%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Operations Manager access required';
  end if;

  v_pos:=array_position(v_order,p_field);
  if v_pos is null then
    raise exception 'Unsupported Helios field-install check';
  end if;

  select ticket_no into v_ticket
  from public.prep_tickets
  where id=p_prep_id and status='released'
  for update;

  if not found then
    raise exception 'Helios handoff is not open for field installation';
  end if;

  if v_role='service'::public.app_role and not exists(
    select 1
    from public.job_assignments a
    where a.assigned_role='service'
      and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_ticket))
      and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started','completed')
  ) then
    raise exception 'This Service handoff is not assigned to you';
  end if;

  if not exists(
    select 1
    from public.service_solar_checks
    where prep_ticket_id=p_prep_id and handoff_accepted_at is not null
  ) then
    raise exception 'Accept the IT handoff before starting the field installation';
  end if;

  if coalesce(p_value,false) and v_pos>1 then
    for v_i in 1..v_pos-1 loop
      execute format(
        'select coalesce(%I,false) from public.service_solar_checks where prep_ticket_id=$1',
        v_order[v_i]
      ) into v_prior using p_prep_id;
      if not coalesce(v_prior,false) then
        raise exception 'Complete the previous Helios field-install step before this one.';
      end if;
    end loop;
  end if;

  execute format(
    'update public.service_solar_checks
       set %I=$1,
           helios_field_completed_at=null,
           helios_field_completed_by=null,
           helios_field_completed_by_name=null,
           helios_owner_verified_at=null,
           helios_owner_verified_by=null,
           helios_owner_verified_by_name=null,
           updated_at=now()
     where prep_ticket_id=$2',
    p_field
  ) using coalesce(p_value,false),p_prep_id;

  if not coalesce(p_value,false) and v_pos<array_length(v_order,1) then
    for v_i in v_pos+1..array_length(v_order,1) loop
      execute format(
        'update public.service_solar_checks
           set %I=false, updated_at=now()
         where prep_ticket_id=$1',
        v_order[v_i]
      ) using p_prep_id;
    end loop;
  end if;

  select * into v_row
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_resolve_swap_unit_v1(p_item_id uuid, p_used boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_item public.prep_items%rowtype;
  v_prep public.prep_tickets%rowtype;
  v_name text;
  v_key text;
  v_it record;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Service or Owner access required'; end if;

  select * into v_item from public.prep_items where id=p_item_id for update;
  if not found or v_item.purpose<>'SWAP'::public.prep_purpose then raise exception 'SWAP replacement unit not found'; end if;
  if nullif(trim(coalesce(v_item.unit_tag,'')),'') is null then raise exception 'The SWAP replacement unit must have a unit tag before Service can resolve it'; end if;

  select * into v_prep from public.prep_tickets where id=v_item.prep_ticket_id;
  if not found or v_prep.status not in ('released'::public.prep_status,'closed'::public.prep_status) then raise exception 'Service must receive the IT handoff before resolving the SWAP unit'; end if;

  if v_role='service'::public.app_role and not exists(
    select 1 from public.job_assignments a
    where trim(a.ticket_no)=trim(v_prep.ticket_no)
      and a.assigned_role='service' and a.assignee_user_id=auth.uid()
      and a.status in ('assigned','started')
  ) and v_prep.closed_by is distinct from auth.uid() then raise exception 'This SWAP is assigned to another Service Tech'; end if;

  if v_item.swap_outcome is not null then
    if (p_used and v_item.swap_outcome='installed') or (not p_used and v_item.swap_outcome='returned_unused') then
      return jsonb_build_object('item_id',v_item.id,'outcome',v_item.swap_outcome,'already_recorded',true);
    end if;
    raise exception 'This SWAP unit already has a different outcome. Owner review is required to change it.';
  end if;

  v_name:=public.actor_display_name();
  v_key:=public.normalize_unit_key(v_item.unit_tag);

  if p_used then
    update public.prep_items
    set swap_outcome='installed', swap_outcome_by=auth.uid(), swap_outcome_by_name=v_name, swap_outcome_at=now(),
        swap_installed_site=nullif(trim(coalesce(v_prep.site,'')),''),
        swap_site_registration_status='pending_it', swap_site_registered_by=null, swap_site_registered_by_name=null, swap_site_registered_at=null
    where id=v_item.id;

    update public.unit_registry
    set lifecycle_status='deployed', ticket_no=v_prep.ticket_no, prep_ticket_id=v_prep.id, prep_item_id=v_item.id,
        current_holder_id=null, current_holder_name=null,
        current_site=nullif(trim(coalesce(v_prep.site,'')),''),
        last_event='Service confirmed SWAP installed at '||coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'customer site')||
          ' on MHelpDesk #'||v_prep.ticket_no||' — IT site registration pending',
        updated_at=now()
    where unit_key=v_key;

    update public.asset_inventory
    set availability_status='assigned', assigned_to=null, assigned_to_name=null,
        last_event='SWAP installed at '||coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'customer site')||
          ' — IT site registration pending · MHelpDesk #'||v_prep.ticket_no, updated_at=now()
    where unit_key=v_key;

    for v_it in select user_id from public.profiles where active=true and archived_at is null and role='it' loop
      perform public.enqueue_app_notification(v_it.user_id,'swap_site_registration','SWAP installed — register unit at site',
        'Service Tech '||v_name||' confirmed '||v_item.equipment_type||' '||v_item.unit_tag||' was installed at '||
        coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'the customer site')||' for MHelpDesk #'||v_prep.ticket_no||
        '. Complete the IT site-registration task.',null,v_prep.ticket_no,v_item.unit_tag);
    end loop;

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values('SWAP REPLACEMENT INSTALLED',auth.uid(),v_name,v_prep.ticket_no,
      'Service confirmed replacement '||v_item.equipment_type||' '||v_item.unit_tag||' was installed at '||
      coalesce(nullif(trim(coalesce(v_prep.site,'')),''),'the customer site')||
      '. The OLD field unit must return through IT Intake. IT site registration is now ready.');

    return jsonb_build_object('item_id',v_item.id,'outcome','installed','site',v_prep.site,'old_unit_return_required',true,'it_site_registration_required',true);
  else
    update public.prep_items
    set swap_outcome='returned_unused', swap_outcome_by=auth.uid(), swap_outcome_by_name=v_name, swap_outcome_at=now(),
        swap_installed_site=null, swap_site_registration_status='not_required',
        swap_site_registered_by=null, swap_site_registered_by_name=null, swap_site_registered_at=null
    where id=v_item.id;

    update public.unit_registry
    set lifecycle_status='assigned_to_tech', ticket_no=v_prep.ticket_no, prep_ticket_id=v_prep.id, prep_item_id=v_item.id,
        current_holder_id=auth.uid(), current_holder_name=v_name, current_site=null,
        last_event='Service confirmed prepared SWAP replacement was not used — physical Service Return to IT Intake required',
        updated_at=now()
    where unit_key=v_key;

    insert into public.reports(kind,actor_id,actor_name,ticket_no,text)
    values('SWAP REPLACEMENT NOT USED',auth.uid(),v_name,v_prep.ticket_no,
      'Service confirmed replacement '||v_item.equipment_type||' '||v_item.unit_tag||
      ' was NOT installed. Service must now physically return this exact replacement through Service Return → IT Intake.');

    return jsonb_build_object('item_id',v_item.id,'outcome','returned_unused','replacement_return_required',true,'old_unit_return_required',false,'it_site_registration_required',false);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_solar_context(p_prep_id uuid)
 RETURNS TABLE(need_solar boolean, need_stand boolean, has_helios boolean, assignment_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ticket text;
  v_role public.app_role;
  v_assignment uuid;
  v_need_stand boolean := false;
  v_has_helios boolean := false;
begin
  v_role := public.current_app_role();
  if v_role is null or v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select ticket_no into v_ticket
  from public.prep_tickets
  where id=p_prep_id;
  if not found then raise exception 'Equipment prep not found'; end if;

  select a.id into v_assignment
  from public.job_assignments a
  where a.assigned_role='service'
    and a.status in ('assigned','started','completed')
    and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_ticket))
    and (
      v_role='owner'::public.app_role
      or a.assignee_user_id=auth.uid()
    )
  order by
    case when a.prep_ticket_id=p_prep_id then 0 else 1 end,
    a.assigned_at desc
  limit 1;

  select exists(
    select 1 from public.prep_items i
    where i.prep_ticket_id=p_prep_id
      and i.equipment_type in ('Solar Stand')
  ) into v_need_stand;

  select exists(
    select 1 from public.prep_items i
    where i.prep_ticket_id=p_prep_id
      and i.equipment_type='Helios'
  ) into v_has_helios;

  if v_assignment is not null then
    v_need_stand := v_need_stand or exists(
      select 1
      from public.job_assignments a,
           lateral jsonb_array_elements(coalesce(a.equipment_manifest,'[]'::jsonb)) m
      where a.id=v_assignment
        and m->>'category'='stand'
        and m->>'label' in ('Solar Stand')
        and coalesce((m->>'qty')::integer,0)>0
    );

    v_has_helios := v_has_helios or exists(
      select 1
      from public.job_assignments a,
           lateral jsonb_array_elements(coalesce(a.equipment_manifest,'[]'::jsonb)) m
      where a.id=v_assignment
        and m->>'category'='device'
        and m->>'label'='Helios'
        and coalesce((m->>'qty')::integer,0)>0
    );
  end if;

  return query select (v_need_stand or v_has_helios),v_need_stand,v_has_helios,v_assignment;
end;
$function$

CREATE OR REPLACE FUNCTION public.service_solar_context_v2(p_prep_id uuid)
 RETURNS TABLE(need_solar boolean, need_stand boolean, has_helios boolean, has_ranger boolean, solar_spotter_count integer, ranger_count integer, expected_batteries integer, expected_solar_panels integer, assignment_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ticket text; v_role public.app_role; v_assignment uuid;
  v_spotters integer:=0; v_rangers integer:=0; v_helios integer:=0; v_explicit_stands integer:=0;
  v_owner_panels integer:=0; v_prep_panels integer:=0;
begin
  v_role:=public.current_app_role();
  if v_role is null or v_role not in ('service'::public.app_role,'owner'::public.app_role) then raise exception 'Service or Owner access required'; end if;
  select ticket_no,coalesce(solar_panel_qty,0) into v_ticket,v_prep_panels from public.prep_tickets where id=p_prep_id;
  if not found then raise exception 'Equipment prep not found'; end if;
  select
    count(*) filter(where equipment_type='Solar Spotter' and purpose='DELIVERY'::public.prep_purpose),
    count(*) filter(where equipment_type='Ranger' and purpose='DELIVERY'::public.prep_purpose),
    count(*) filter(where equipment_type='Helios' and purpose in ('DELIVERY'::public.prep_purpose,'SWAP'::public.prep_purpose,'BACKUP'::public.prep_purpose)),
    count(*) filter(where equipment_type in ('Solar Stand') and purpose='DELIVERY'::public.prep_purpose)
  into v_spotters,v_rangers,v_helios,v_explicit_stands
  from public.prep_items where prep_ticket_id=p_prep_id;
  select a.id,coalesce(a.solar_panel_qty,0) into v_assignment,v_owner_panels
  from public.job_assignments a
  where a.assigned_role='service' and a.status in ('assigned','started','completed')
    and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_ticket))
    and (v_role='owner'::public.app_role or a.assignee_user_id=auth.uid())
  order by case when a.prep_ticket_id=p_prep_id then 0 else 1 end,a.assigned_at desc limit 1;
  return query select
    (v_spotters>0 or v_rangers>0 or v_helios>0 or v_explicit_stands>0),
    (v_spotters>0 or v_explicit_stands>0),(v_helios>0),(v_rangers>0),
    v_spotters,v_rangers,(v_spotters*4)+v_rangers+v_helios,greatest(v_rangers,v_owner_panels,v_prep_panels),v_assignment;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_job_assignment_status(p_assignment_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_assignment public.job_assignments%rowtype;
  v_departure jsonb;
begin
  if p_status not in ('started','completed') then
    raise exception 'Invalid assignment status.';
  end if;

  select * into v_assignment
  from public.job_assignments
  where id=p_assignment_id
    and assignee_user_id=auth.uid()
  for update;

  if not found then
    raise exception 'Assignment not found or not assigned to you.';
  end if;

  if p_status='started' then
    if v_assignment.status='started' then
      return;
    end if;
    if v_assignment.status<>'assigned' then
      raise exception 'Assignment is no longer available to start.';
    end if;

    if v_assignment.assigned_role='it'
       and lower(coalesce(v_assignment.work_type,''))='pickup'
       and not exists(
         select 1 from public.unit_returns r
         where trim(r.ticket_no)=trim(v_assignment.ticket_no)
           and r.status='waiting_it'
       ) then
      raise exception 'WAITING FOR SERVICE RETURN. IT cannot start this pickup until Service checks returned equipment into IT Intake.';
    end if;

    if v_assignment.assigned_role='service'
       and coalesce(v_assignment.requires_it_handoff,false)
       and not exists(
         select 1 from public.prep_tickets p
         where trim(p.ticket_no)=trim(v_assignment.ticket_no)
           and p.status in ('released','closed')
       ) then
      raise exception 'WAITING FOR IT HANDOFF. Service cannot start until IT completes the required handoff.';
    end if;

    if v_assignment.assigned_role='service' then
      v_departure:=public.service_departure_readiness_v1(auth.uid());
      if coalesce((v_departure->>'departure_ready')::boolean,false) is not true then
        raise exception 'NOT READY TO LEAVE SHOP. Complete the daily Truck / Trailer Inspection and required permanent truck inventory check/restock before starting a new Service job.';
      end if;
    end if;

    update public.job_assignments
    set status='started',
        started_at=coalesce(started_at,now()),
        updated_at=now()
    where id=p_assignment_id;
    return;
  end if;

  -- completed
  if v_assignment.status='completed' then
    return;
  end if;
  if v_assignment.status<>'started' then
    raise exception 'Start this Tech Check job before completing it.';
  end if;

  if lower(coalesce(v_assignment.work_type,''))='pickup' then
    raise exception 'PICKUP completion is controlled by Service Return and IT Intake. Finish the required return/intake steps instead of manually completing the assignment.';
  end if;

  if v_assignment.assigned_role='service' then
    if exists(
      select 1
      from public.field_escalations f
      where trim(f.ticket_no)=trim(v_assignment.ticket_no)
        and f.resolved_at is null
    ) then
      raise exception 'This Service job has an unresolved field escalation. Resolve it before completing Tech Check.';
    end if;

    if coalesce(v_assignment.requires_it_handoff,false)
       or v_assignment.prep_ticket_id is not null then
      if not exists(
        select 1
        from public.prep_tickets p
        where (
          p.id=v_assignment.prep_ticket_id
          or trim(p.ticket_no)=trim(v_assignment.ticket_no)
        )
        and p.status='closed'
      ) then
        raise exception 'This Service job must finish through the authoritative equipment/field closeout before the assignment can be completed.';
      end if;
    end if;
  end if;

  update public.job_assignments
  set status='completed',
      completed_at=coalesce(completed_at,now()),
      updated_at=now()
  where id=p_assignment_id
    and status='started';
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_service_solar_progress_v1(p_prep_id uuid)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_prep public.prep_tickets%rowtype;
  v_row public.service_solar_checks%rowtype;
  v_spotters int:=0;
  v_rangers int:=0;
  v_helios int:=0;
  v_expected_panels int:=0;
  v_owner_panels int:=0;
  v_battery_count int:=0;
  v_description text:='';
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=p_prep_id and status='released';
  if not found then raise exception 'Equipment must be waiting for Service'; end if;

  select * into v_row
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id
  for update;
  if not found then raise exception 'Start the Service pre-trip first'; end if;

  select
    count(*) filter(where equipment_type='Solar Spotter' and purpose='DELIVERY'::public.prep_purpose),
    count(*) filter(where equipment_type='Ranger' and purpose='DELIVERY'::public.prep_purpose),
    count(*) filter(where equipment_type='Helios' and purpose in ('DELIVERY'::public.prep_purpose,'SWAP'::public.prep_purpose,'BACKUP'::public.prep_purpose))
  into v_spotters,v_rangers,v_helios
  from public.prep_items
  where prep_ticket_id=p_prep_id;

  select coalesce(max(a.solar_panel_qty),0)
  into v_owner_panels
  from public.job_assignments a
  where a.assigned_role='service'
    and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_prep.ticket_no));

  v_expected_panels:=greatest(v_rangers,v_owner_panels,coalesce(v_prep.solar_panel_qty,0));

  if v_spotters>0 then
    if nullif(trim(coalesce(v_row.stand_tag,'')),'') is null or not v_row.stand_verified then
      raise exception 'Verify the exact Solar Stand tag before continuing';
    end if;
    if v_row.battery_configuration='agm_4x_12v_110ah' then
      v_battery_count:=v_battery_count+(v_spotters*4);
      v_description:=v_spotters||' Solar Stand(s): 4 x AGM 12V 110Ah each';
    elsif v_row.battery_configuration='single_12v_350ah' then
      v_battery_count:=v_battery_count+v_spotters;
      v_description:=v_spotters||' Solar Stand(s): 1 x 12V 350Ah each';
    else
      raise exception 'Choose the Solar Spotter battery setup';
    end if;
  end if;

  if not v_row.mppt_updated_ok then raise exception 'Verify the MPPT firmware / configuration'; end if;
  if not v_row.mppt_tested_ok then raise exception 'Verify the MPPT is powered and working'; end if;

  if v_expected_panels>0 then
    if v_row.solar_panel_count<>v_expected_panels or not v_row.solar_panels_verified then
      raise exception 'Verify the required loose solar panel count';
    end if;
  end if;

  if not v_row.batteries_charged_ok then raise exception 'Verify the required battery / battery-box setup'; end if;
  if not v_row.solar_charging_ok then raise exception 'Verify active charging through MPPT / PV'; end if;

  if v_rangers>0 then
    v_battery_count:=v_battery_count+v_rangers;
    v_description:=trim(both ' · ' from v_description||' · '||v_rangers||' x LiTime 12V 110Ah');
  end if;

  if v_helios>0 then
    if not v_row.helios_yard_pv_connected_ok then raise exception 'Connect the Helios unit to the yard tower solar panel'; end if;
    if not v_row.helios_yard_switch_pv_ok then raise exception 'Flip the internal Helios switch to PV'; end if;
    if not v_row.helios_yard_victron_bluetooth_ok then raise exception 'Connect to the Helios MPPT in the Victron Bluetooth app'; end if;
    if not v_row.helios_yard_updates_status_ok then raise exception 'Verify the MPPT is current and healthy in Victron'; end if;
    if not coalesce(v_row.helios_battery_box_charging_ok,false) then raise exception 'Verify the internal Helios battery box is present and charged'; end if;
    if not v_row.helios_yard_solar_charging_ok then raise exception 'Verify solar charging from the yard tower'; end if;
    if not v_row.helios_yard_ptz_wrapped_ok then raise exception 'Remove the PTZ and bubble wrap it for transport'; end if;

    v_battery_count:=v_battery_count+v_helios;
    v_description:=trim(both ' · ' from v_description||' · '||v_helios||' Helios battery box(es)');
    if v_spotters=0 and v_rangers=0 then
      update public.service_solar_checks
      set battery_configuration='helios_battery_box'
      where prep_ticket_id=p_prep_id;
    end if;
  elsif v_spotters=0 and v_rangers>0 then
    update public.service_solar_checks
    set battery_configuration='litime_1x_12v_110ah'
    where prep_ticket_id=p_prep_id;
  end if;

  if v_description='' then v_description:='Battery system used for charging verification'; end if;

  update public.service_solar_checks
  set battery_count=v_battery_count,
      battery_description=v_description,
      completed_at=now(),
      updated_at=now()
  where prep_ticket_id=p_prep_id
  returning * into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_service_solar_evidence(p_prep_id uuid, p_category text, p_kind text, p_storage_path text, p_original_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_status public.prep_status;
  v_id uuid;
  v_name text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Operations Manager access required';
  end if;

  if p_category not in ('solar_stand','batteries','mppt','helios_cerbo_mppt','helios_yard','helios_install') then
    raise exception 'Invalid Solar / Helios evidence category';
  end if;
  if p_kind not in ('photo','signature') then
    raise exception 'Invalid evidence type';
  end if;
  if nullif(trim(p_storage_path),'') is null then
    raise exception 'Evidence file path is required';
  end if;
  if split_part(p_storage_path,'/',1)<>auth.uid()::text then
    raise exception 'Evidence path does not belong to this technician';
  end if;

  select status into v_status
  from public.prep_tickets
  where id=p_prep_id
  for update;

  if not found then raise exception 'Equipment prep not found'; end if;
  if v_status<>'released'::public.prep_status then
    raise exception 'Service Solar / Helios evidence can only be added while equipment is waiting for Service';
  end if;

  v_name:=public.actor_display_name();

  if p_kind='signature' then
    delete from public.service_solar_evidence
    where prep_ticket_id=p_prep_id
      and category=p_category
      and kind='signature'
      and created_by=auth.uid()
      and storage_path<>trim(p_storage_path);
  end if;

  insert into public.service_solar_evidence(
    prep_ticket_id,category,kind,storage_path,original_name,created_by,created_by_name
  )
  values(
    p_prep_id,p_category,p_kind,trim(p_storage_path),
    nullif(trim(p_original_name),''),
    auth.uid(),v_name
  )
  on conflict(storage_path) do update
  set original_name=excluded.original_name
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_service_solar_progress_v1(p_prep_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_ticket text;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select ticket_no into v_ticket
  from public.prep_tickets
  where id=p_prep_id and status='released';

  if not found then
    raise exception 'Service handoff not found or no longer waiting for Service';
