CREATE OR REPLACE FUNCTION public.save_service_solar_progress_v1(p_prep_id uuid, p_field text, p_value text)
 RETURNS service_solar_checks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role public.app_role;
  v_prep public.prep_tickets%rowtype;
  v_actor_id uuid;
  v_actor_name text;
  v_assignment_id uuid;
  v_row public.service_solar_checks%rowtype;
begin
  v_role:=public.current_app_role();
  if v_role not in ('service'::public.app_role,'owner'::public.app_role) then
    raise exception 'Service or Owner access required';
  end if;

  select * into v_prep
  from public.prep_tickets
  where id=p_prep_id and status='released';

  if not found then
    raise exception 'Equipment must be waiting for Service';
  end if;

  v_actor_id:=auth.uid();
  v_actor_name:=public.actor_display_name();

  select a.id
  into v_assignment_id
  from public.job_assignments a
  where a.assigned_role='service'
    and (a.prep_ticket_id=p_prep_id or trim(a.ticket_no)=trim(v_prep.ticket_no))
    and a.status in ('assigned','started','completed')
    and (v_role='owner'::public.app_role or a.assignee_user_id=auth.uid())
  order by case when a.prep_ticket_id=p_prep_id then 0 else 1 end,a.assigned_at desc
  limit 1;

  if coalesce(v_prep.is_test,false) and v_role='owner'::public.app_role then
    select a.id,a.assignee_user_id,coalesce(a.assignee_name,p.full_name,p.username,'Test Service')
    into v_assignment_id,v_actor_id,v_actor_name
    from public.job_assignments a
    left join public.profiles p on p.user_id=a.assignee_user_id
    where trim(a.ticket_no)=trim(v_prep.ticket_no)
      and a.assigned_role='service'
      and a.created_from='owner_test_center'
      and a.assignee_user_id is not null
    order by a.assigned_at desc
    limit 1;

    if v_actor_id is null then
      v_actor_id:=auth.uid();
      v_actor_name:=public.actor_display_name();
    end if;
  end if;

  insert into public.service_solar_checks(
    prep_ticket_id,assignment_id,service_tech_id,service_tech_name,updated_at
  ) values(
    p_prep_id,v_assignment_id,v_actor_id,v_actor_name,now()
  )
  on conflict(prep_ticket_id) do update set
    assignment_id=coalesce(excluded.assignment_id,public.service_solar_checks.assignment_id),
    service_tech_id=excluded.service_tech_id,
    service_tech_name=excluded.service_tech_name,
    updated_at=now();

  case p_field
    when 'stand_tag' then
      update public.service_solar_checks set stand_tag=nullif(trim(p_value),''),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'stand_verified' then
      update public.service_solar_checks set stand_verified=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'battery_configuration' then
      if p_value not in ('agm_4x_12v_110ah','single_12v_350ah','litime_1x_12v_110ah','helios_battery_box','mixed') then
        raise exception 'Invalid battery configuration';
      end if;
      update public.service_solar_checks set battery_configuration=p_value,updated_at=now() where prep_ticket_id=p_prep_id;
    when 'mppt_updated_ok' then
      update public.service_solar_checks set mppt_updated_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'mppt_tested_ok' then
      update public.service_solar_checks set mppt_tested_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'cerbo_updated_ok' then
      update public.service_solar_checks set cerbo_updated_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'cerbo_online_ok' then
      update public.service_solar_checks set cerbo_online_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'solar_panel_count' then
      update public.service_solar_checks set solar_panel_count=greatest(coalesce(p_value::int,0),0),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'solar_panels_verified' then
      update public.service_solar_checks set solar_panels_verified=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'batteries_charged_ok' then
      update public.service_solar_checks set batteries_charged_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'solar_charging_ok' then
      update public.service_solar_checks set solar_charging_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_battery_box_charging_ok' then
      update public.service_solar_checks set helios_battery_box_charging_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_pv_connected_ok' then
      update public.service_solar_checks set helios_yard_pv_connected_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_switch_pv_ok' then
      update public.service_solar_checks set helios_yard_switch_pv_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_victron_bluetooth_ok' then
      update public.service_solar_checks set helios_yard_victron_bluetooth_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_updates_status_ok' then
      update public.service_solar_checks set helios_yard_updates_status_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_solar_charging_ok' then
      update public.service_solar_checks set helios_yard_solar_charging_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    when 'helios_yard_ptz_wrapped_ok' then
      update public.service_solar_checks set helios_yard_ptz_wrapped_ok=coalesce(p_value::boolean,false),updated_at=now() where prep_ticket_id=p_prep_id;
    else
      raise exception 'Unsupported Service pre-trip field';
  end case;

  select * into v_row
  from public.service_solar_checks
  where prep_ticket_id=p_prep_id;

  return v_row;
end;
$function$
